public with sharing class RecordSearchService {

    public class SearchException extends Exception {}

    public static List<SObject> search(String objectApiName,
                                       List<String> fields,
                                       Map<String, Object> filters,
                                       String orderByField,
                                       Integer maxRows) {

        // 1. Resolve object type (case‑insensitive)
        if (objectApiName == null || objectApiName.isEmpty()) {
            throw new SearchException('Object API name cannot be null or empty.');
        }
        String apiName = objectApiName.trim();

        Schema.SObjectType sto = null;
        for (Schema.SObjectType s : Schema.getGlobalDescribe().values()) {
            if (s.getDescribe().getName().equalsIgnoreCase(apiName)) {
                sto = s;
                break;
            }
        }
        if (sto == null) {
            throw new SearchException('Object ' + apiName + ' does not exist.');
        }
        Schema.DescribeSObjectResult d = sto.getDescribe();

        // Check object‑level read access
        if (!d.isAccessible()) {
            throw new SearchException('The running user does not have read access to object ' + apiName + '.');
        }

        // 2. Validate and resolve requested fields
        if (fields == null || fields.isEmpty()) {
            throw new SearchException('Fields list cannot be null or empty.');
        }

        Map<String, String> fieldExactMap = new Map<String, String>();

        for (String f : fields) {
            if (f == null || f.isEmpty()) {
                throw new SearchException('Field name cannot be null or empty.');
            }
            String exact = resolveFieldExact(f, d);
            // Verify FLS
            Schema.DescribeFieldResult df = d.fields.getMap().get(exact).getDescribe();
            if (!df.isAccessible()) {
                throw new SearchException('The running user does not have read access to field ' + exact + '.');
            }
            fieldExactMap.put(f, exact);
        }

        // 3. Validate filters (if present)
        Map<String, String> filterExactMap = new Map<String, String>();

        if (filters != null && !filters.isEmpty()) {
            for (String key : filters.keySet()) {
                if (key == null || key.isEmpty()) {
                    throw new SearchException('Filter key cannot be null or empty.');
                }
                String exact = resolveFieldExact(key, d);
                Schema.DescribeFieldResult df = d.fields.getMap().get(exact).getDescribe();
                if (!df.isAccessible()) {
                    throw new SearchException('The running user does not have read access to filter field ' + exact + '.');
                }
                if (!df.isFilterable()) {
                    throw new SearchException('Field ' + exact + ' is not filterable and cannot be used in a filter.');
                }
                filterExactMap.put(key, exact);
            }
        }

        // 4. Validate orderByField
        String resolvedOrderBy = null;
        if (orderByField != null && !orderByField.isEmpty()) {
            String exact = resolveFieldExact(orderByField, d);
            Schema.DescribeFieldResult df = d.fields.getMap().get(exact).getDescribe();
            if (!df.isAccessible()) {
                throw new SearchException('The running user does not have read access to order‑by field ' + exact + '.');
            }
            if (!df.isSortable()) {
                throw new SearchException('Field ' + exact + ' is not sortable and cannot be used for ORDER BY.');
            }
            resolvedOrderBy = exact;
        }

        // 5. Validate maxRows
        if (maxRows == null || maxRows < 1 || maxRows > 200) {
            throw new SearchException('maxRows must be between 1 and 200.');
        }

        // 6. Build SELECT clause
        Set<String> selectSet = new Set<String>();
        selectSet.add('Id');
        for (String exact : fieldExactMap.values()) {
            selectSet.add(exact);
        }
        List<String> selectList = new List<String>(selectSet);
        String selectClause = 'SELECT ' + String.join(selectList, ', ');

        // 7. Build WHERE clause and bind values (SOQL injection safe)
        String whereClause = '';
        Map<Schema.SObjectField, Object> bindVals = new Map<Schema.SObjectField, Object>();

        if (filters != null && !filters.isEmpty()) {
            Integer idx = 0;
            for (String key : filters.keySet()) {
                String exact = filterExactMap.get(key);
                if (exact == null) continue;
                Object val = filters.get(key);
                Schema.DescribeFieldResult df = d.fields.getMap().get(exact).getDescribe();
                Schema.SObjectField sf = df.getSobjectField();
                bindVals.put(sf, val);
                String placeholder = ':' + exact;
                whereClause += (idx > 0 ? ' AND ' : ' WHERE ');
                whereClause += exact + ' = ' + placeholder;
                idx++;
            }
        }

        // 8. Build ORDER BY clause
        String orderByClause = '';
        if (resolvedOrderBy != null) {
            orderByClause = ' ORDER BY ' + resolvedOrderBy + ' ASC';
        }

        // 9. Assemble full query WITH SECURITY_ENFORCED
        String query = selectClause
                       + ' FROM ' + apiName
                       + ' WITH SECURITY_ENFORCED'
                       + whereClause
                       + orderByClause
                       + ' LIMIT ' + String.valueOf(maxRows);

        // 10. Execute query respecting sharing and FLS
        List<SObject> results;
        try {
            if (bindVals.isEmpty()) {
                results = Database.query(query);
            } else {
                results = Database.query(query, bindVals);
            }
        } catch (QueryException qe) {
            throw new SearchException('SOQL query failed: ' + qe.getMessage());
        }

        return results;
    }

    private static String resolveFieldExact(String fieldName, Schema.DescribeSObjectResult d) {
        if (fieldName == null || fieldName.isEmpty()) {
            throw new SearchException('Field name cannot be null or empty.');
        }
        String search = fieldName.trim();
        // Case‑insensitive lookup via DescribeFieldResult
        for (Schema.DescribeFieldResult df : d.fields.getMap().values()) {
            if (df.getName().equalsIgnoreCase(search)) {
                return df.getName();
            }
        }
        // Exact match fallback
        if (d.fields.getMap().containsKey(search)) {
            return search;
        }
        throw new SearchException('Field ' + search + ' is not a field of the specified object.');
    }
}
