public with sharing class ContactLookupAction {
    public static class Request {
        @InvocableVariable(label = 'Email', required = true)
        public String email;
    }

    public static class Result {
        @InvocableVariable(label = 'Contact ID')
        public Id contactId;

        @InvocableVariable(label = 'Found')
        public Boolean found;
    }

    @InvocableMethod(label = 'Find Contact by Email')
    public static List<Result> find(List<Request> requests) {
        List<Result> results = new List<Result>(requests.size());

        // Collect normalized (trimmed, lowercased) emails for a single SOQL query
        Set<String> searchEmails = new Set<String>();
        for (Request req : requests) {
            if (req.email != null && req.email.trim().length() > 0) {
                searchEmails.add(req.email.trim().toLowerCase());
            }
        }

        // Single SOQL query respecting the running user's sharing;
        // find the earliest CreatedDate contact per normalized email
        Map<String, Contact> earliestByEmail = new Map<String, Contact>();
        if (!searchEmails.isEmpty()) {
            for (Contact c : [SELECT Id, Email, CreatedDate FROM Contact WHERE Email IN :searchEmails]) {
                String norm = c.Email.trim().toLowerCase();
                if (!earliestByEmail.containsKey(norm)) {
                    earliestByEmail.put(norm, c);
                } else {
                    Contact existing = earliestByEmail.get(norm);
                    if (c.CreatedDate < existing.CreatedDate) {
                        earliestByEmail.put(norm, c);
                    }
                }
            }
        }

        // Build results maintaining the same order as the input requests
        for (Request req : requests) {
            Result res = new Result();
            if (req.email != null && req.email.trim().length() > 0) {
                String norm = req.email.trim().toLowerCase();
                if (earliestByEmail.containsKey(norm)) {
                    res.contactId = earliestByEmail.get(norm).Id;
                    res.found = true;
                } else {
                    res.contactId = null;
                    res.found = false;
                }
            } else {
                res.contactId = null;
                res.found = false;
            }
            results.add(res);
        }

        return results;
    }
}
