public class OpportunityPipelineHandler {
    // Static depth counter to prevent recursive trigger execution when the
    // legacy AccountTrigger updates opportunities.
    private static Integer handlerDepth = 0;

    public void afterInsert(List<Opportunity> newOpps) {
        handlerDepth++;
        try {
            if (handlerDepth > 1) {
                return;
            }
            Set<Id> accountIds = new Set<Id>();
            for (Opportunity o : newOpps) {
                if (o.AccountId != null) {
                    accountIds.add(o.AccountId);
                }
            }
            updateAccountPipelineFields(accountIds);
        } finally {
            handlerDepth--;
        }
    }

    public void afterUpdate(List<Opportunity> newOpps, List<Opportunity> oldOpps) {
        handlerDepth++;
        try {
            if (handlerDepth > 1) {
                return;
            }
            Set<Id> accountIds = new Set<Id>();
            Map<Id, Opportunity> newMap = new Map<Id, Opportunity>(newOpps);
            Map<Id, Opportunity> oldMap = new Map<Id, Opportunity>(oldOpps);
            for (Opportunity o : newOpps) {
                Opportunity old = oldMap.get(o.Id);
                if (old == null) continue;
                Boolean changed = false;
                if (old.IsClosed != o.IsClosed) {
                    changed = true;
                } else if (old.IsClosed == false && o.IsClosed == false && old.Amount != o.Amount) {
                    changed = true;
                } else if (old.AccountId != o.AccountId) {
                    changed = true;
                }
                if (changed) {
                    if (old.AccountId != null) accountIds.add(old.AccountId);
                    if (o.AccountId != null) accountIds.add(o.AccountId);
                }
            }
            updateAccountPipelineFields(accountIds);
        } finally {
            handlerDepth--;
        }
    }

    public void afterDelete(List<Opportunity> oldOpps) {
        handlerDepth++;
        try {
            if (handlerDepth > 1) {
                return;
            }
            Set<Id> accountIds = new Set<Id>();
            for (Opportunity o : oldOpps) {
                if (o.AccountId != null) {
                    accountIds.add(o.AccountId);
                }
            }
            updateAccountPipelineFields(accountIds);
        } finally {
            handlerDepth--;
        }
    }

    public void afterUndelete(List<Opportunity> newOpps) {
        handlerDepth++;
        try {
            if (handlerDepth > 1) {
                return;
            }
            Set<Id> accountIds = new Set<Id>();
            for (Opportunity o : newOpps) {
                if (o.AccountId != null) {
                    accountIds.add(o.AccountId);
                }
            }
            updateAccountPipelineFields(accountIds);
        } finally {
            handlerDepth--;
        }
    }

    private void updateAccountPipelineFields(Set<Id> accountIds) {
        if (accountIds.isEmpty()) return;

        Map<Id, AggregateResult> results = new Map<Id, AggregateResult>(
            [SELECT AccountId, SUM(Amount) totalAm, COUNT(Id) oppCount
             FROM Opportunity
             WHERE AccountId IN :accountIds AND IsClosed = false
             GROUP BY AccountId]
        );

        List<Account> accountsToUpdate = new List<Account>();
        for (Id accId : accountIds) {
            // Skip null Ids to avoid DML row error
            if (accId == null) continue;

            Decimal totalAm = 0;
            Integer cnt = 0;
            if (results.containsKey(accId)) {
                totalAm = (Decimal) results.get(accId).get('totalAm');
                cnt = (Integer) results.get(accId).get('oppCount');
            }
            if (totalAm == null) totalAm = 0;
            if (cnt == null) cnt = 0;

            Account acc = new Account(Id = accId);
            acc.FB_Open_Pipeline__c = totalAm;
            acc.FB_Open_Opportunities__c = cnt;
            accountsToUpdate.add(acc);
        }

        if (!accountsToUpdate.isEmpty()) {
            update accountsToUpdate;
        }
    }
}
