public with sharing class OpportunityRollupService {
    public static Map<Id, Decimal> wonAmountThisYear(Set<Id> accountIds) {
        if (accountIds == null || accountIds.isEmpty()) {
            return new Map<Id, Decimal>();
        }

        Map<Id, Decimal> wonByAccount = new Map<Id, Decimal>();
        for (AggregateResult ar : [
            SELECT AccountId accountId, COALESCE(SUM(Amount), 0) total
            FROM Opportunity
            WHERE IsWon = true
              AND AccountId IN :accountIds
              AND CloseDate = THIS_YEAR
            GROUP BY AccountId
        ]) {
            wonByAccount.put(
                (Id) ar.get('accountId'),
                (Decimal) ar.get('total')
            );
        }

        Map<Id, Decimal> result = new Map<Id, Decimal>();
        for (Id accId : accountIds) {
            Decimal val = wonByAccount.get(accId);
            result.put(accId, val != null ? val : 0);
        }
        return result;
    }
}
