global with sharing class Opportunities extends fflib_SObjectDomain {

    // Standard inner class implementing IConstructable
    global class Constructor implements fflib_SObjectDomain.IConstructable {
        global SObject construct(List<SObject> records) {
            return new Opportunities(records);
        }
    }

    // Default constructor that passes SObjectType to super
    public Opportunities() {
        this(Opportunity.sObjectType);
    }

    // Constructor that accepts a Schema.SObjectType and delegates to parent
    public Opportunities(Schema.SObjectType type) {
        super(type);
    }

    // Private constructor used by IConstructable.construct
    private Opportunities(List<SObject> records) {
        this(Opportunity.sObjectType);
    }

    // Validation on insert and update: Amount must not be negative
    public void validateInsert(List<SObject> records) {
        for (SObject record : records) {
            Decimal amount = (Decimal)record.get('Amount');
            if (amount != null && amount < 0) {
                error('Amount cannot be negative.', record, 'Amount');
            }
        }
    }

    // Validation on update
    public void validateUpdate(List<SObject> records, Map<Id, SObject> oldRecords) {
        for (SObject record : records) {
            Decimal newAmount = (Decimal)record.get('Amount');

            // Rule 1: Amount must not be negative
            if (newAmount != null && newAmount < 0) {
                error('Amount cannot be negative.', record, 'Amount');
            }

            // Rule 2: On update, a previously won opportunity cannot have its Amount changed.
            // Closing an opportunity as won and changing its amount in the same update is allowed.
            Id recordId = record.getId();
            SObject oldRecord = oldRecords.get(recordId);
            if (oldRecord != null) {
                String oldStage = (String)oldRecord.get('Stage');
                if (oldStage == 'Closed Won') {
                    Decimal oldAmount = (Decimal)oldRecord.get('Amount');
                    // Only error if the amount actually changed;
                    // closing as won and changing amount in the same update is allowed
                    if (oldAmount != newAmount) {
                        error('Amount cannot change on a won opportunity.', record, 'Amount');
                    }
                }
            }
        }
    }

    // Helper method to record errors via fflib's error mechanism
    // This populates fflib_SObjectDomain.Errors for unit tests
    global static void error(String message, SObject record, String field) {
        fflib_SObjectDomain.Errors.addError(record, field, message);
    }
}
