public with sharing class LineItemDiscountHandler {
    // Static cache to avoid repeated SOQL queries when the same product appears on multiple lines (e.g., CPQ quotes with up to 200 lines).
    private static Map<Id, Decimal> discountCache = new Map<Id, Decimal>();

    public static void handleTrigger(List<OpportunityLineItem> newLines) {
        for (OpportunityLineItem line : newLines) {
            // Only set the discount when it is explicitly null; preserve existing values including 0.
            if (line.Discount == null) {
                // Populate the cache on first lookup for this product ID.
                if (!discountCache.containsKey(line.Product2Id)) {
                    discountCache.put(line.Product2Id, PricingRules.standardDiscountFor(line.Product2Id));
                }
                line.Discount = discountCache.get(line.Product2Id);
            }
            // Lines that already have a Discount (including 0) are left unchanged.
        }
    }
}
