public with sharing class RenewalReminderService {

    /**
     * Sends a renewal reminder email to each opportunity's owner.
     * Emails are sent in a single bulk invocation to stay within governor limits.
     * If one email fails, the remaining emails still go out.
     *
     * @param opportunityIds List of Opportunity IDs to process (up to 200 per call)
     * @return The number of emails sent successfully
     */
    public static Integer sendReminders(List<Id> opportunityIds) {
        Integer emailsSent = 0;

        if (opportunityIds == null || opportunityIds.isEmpty()) {
            return 0;
        }

        // Build a list of email messages, one per opportunity, in a single loop
        List<Messaging.SingleEmailMessage> emails = new List<Messaging.SingleEmailMessage>();

        for (Opportunity opp : [SELECT Id, Name, CloseDate, OwnerId FROM Opportunity WHERE Id IN :opportunityIds]) {
            Messaging.SingleEmailMessage email = new Messaging.SingleEmailMessage();
            email.setTargetObjectId(opp.OwnerId);
            email.setSaveAsActivity(false);
            email.setSubject('Renewal due: ' + opp.Name);
            email.setPlainTextBody(
                'A renewal is due for opportunity: ' + opp.Name +
                '. The close date is ' + opp.CloseDate + '.'
            );
            emails.add(email);
        }

        // Single sendEmail call for all collected messages.
        // Messaging.sendEmail does not halt on individual failures;
        // results are returned per email so we can count successes.
        List<Messaging.SendEmailResult> results = Messaging.sendEmail(emails);

        for (Messaging.SendEmailResult result : results) {
            if (result.isSuccess()) {
                emailsSent++;
            } else {
                // Log failures without preventing other emails from being processed
                for (Messaging.SendEmailError error : result.getErrors()) {
                    System.debug('Email failed for opportunity Id ' + error.getId() + ': ' + error.getMessage());
                }
            }
        }

        return emailsSent;
    }
}
