import { LightningElement, api, wire } from 'lwc';
import { getRecord } from 'lightning/uiRecordApi';
import Name from '@salesforce/schema/Account.Name';
import Industry from '@salesforce/schema/Account.Industry';
import AnnualRevenue from '@salesforce/schema/Account.AnnualRevenue';
import OwnerName from '@salesforce/schema/Account.Owner.Name';

const FIELDS = [Name, Industry, AnnualRevenue, OwnerName];

export default class AccountHeader extends LightningElement {
  @api
  recordId;

  @wire(getRecord, { recordId: '$recordId', fields: FIELDS })
  recordData;

  get hasError() {
    return !!this.recordData?.error;
  }

  get hasData() {
    return !!this.recordData?.data;
  }

  get isLoading() {
    return !this.recordData || (!this.recordData.data && !this.recordData.error);
