import { LightningElement, api } from 'lwc';
import { NavigationMixin } from 'lightning/navigation';
import { deleteRecord } from 'lightning/uiRecordApi';
import { ShowToastEvent } from 'lightning/uiPrimeToast';
import { open } from 'lightning/confirm';

export default class OpportunityActionsTable extends NavigationMixin(LightningElement) {
    @api opportunities;

    columns = [
        { label: 'Name', fieldName: 'Name', type: 'text' },
        { label: 'Stage', fieldName: 'StageName', type: 'text' },
        { label: 'Amount', fieldName: 'Amount', type: 'currency' },
        {
            type: 'action',
            typeAttributes: {
                rowActions: [
                    { label: 'View', name: 'view' },
                    { label: 'Edit', name: 'edit' },
                    { label: 'Delete', name: 'delete' }
                ]
            }
        }
    ];

    handleRowAction(event) {
        const actionName = event.detail.action.name;
        const row = event.detail.row;

        switch (actionName) {
            case 'view':
                this[NavigationMixin.Navigate]({
                    recordId: row.Id,
                    actionName: 'view'
                });
                break;

            case 'edit':
                this[NavigationMixin.Navigate]({
                    recordId: row.Id,
                    actionName: 'edit'
                });
                break;

            case 'delete':
                open({
                    header: 'Delete Opportunity',
                    message: `Are you sure you want to delete ${row.Name}?`
                })
                    .then(result => {
                        if (result) {
                            deleteRecord({ recordId: row.Id })
                                .then(() => {
                                    // Remove the deleted row without mutating the parent's array
                                    this.opportunities = this.opportunities.filter(opp => opp.Id !== row.Id);
                                    this.dispatchEvent(
                                        new ShowToastEvent({
                                            title: 'Opportunity deleted',
                                            variant: 'success'
                                        })
                                    );
                                })
                                .catch(error => {
                                    // Keep the row, show error toast with error body message
                                    this.dispatchEvent(
                                        new ShowToastEvent({
                                            title: 'Delete failed',
                                            variant: 'error',
                                            message: error.body.message
                                        })
                                    );
                                });
                        }
                        // if user cancels (result is false), do nothing
                    });
                break;
        }
    }
}
