import { LightningElement, api, track } from 'lwc';

export default class StatusListbox extends LightningElement {
  @api label;
  @api options;
  @api value;

  @track activeIndex = 0;
  @track activeId = 'option-0';
  _prevValue = null;

  // arrow class field referenced in template HTML – avoids arrow function in markup
  handleOptionClick = (index) => {
    this.selectOption(index);
  };

  connectedCallback() {
    super.connectedCallback();
    this._prevValue = this.value;
    this.activeId = 'option-0';
  }

  renderedCallback() {
    super.renderedCallback();
    if (this.value !== this._prevValue) {
      const idx = this._findOptionIndex(this.value);
      this.activeIndex = idx !== -1 ? idx : 0;
      this.activeId = 'option-' + this.activeIndex;
      this._prevValue = this.value;
    }
  }

  _findOptionIndex(val) {
    if (!this.options || val === undefined || val === null) return -1;
    for (let i = 0; i < this.options.length; i++) {
      if (this.options[i].value === val) return i;
    }
    return -1;
  }

  handleKeydown(event) {
    const key = event.key;
    const validKeys = ['ArrowDown', 'ArrowUp', 'Home', 'End', 'Enter', ' '];
    if (!validKeys.includes(key)) {
      // let other keys (Tab, etc.) keep their default behaviour
      return;
    }
    event.preventDefault();

    switch (key) {
      case 'ArrowDown':
        this.activeIndex = Math.min(this.activeIndex + 1, this.options.length - 1);
        break;
      case 'ArrowUp':
        this.activeIndex = Math.max(this.activeIndex - 1, 0);
        break;
      case 'Home':
        this.activeIndex = 0;
        break;
      case 'End':
        this.activeIndex = this.options.length - 1;
        break;
      case 'Enter':
      case ' ':
        this.selectOption(this.activeIndex);
        return;
    }
    this.activeId = 'option-' + this.activeIndex;
  }

  selectOption(index) {
    const option = this.options[index];
    if (!option) return;
    const newValue = option.value;
    // dispatch only if the newly selected value differs from the current value
    if (newValue === this.value) {
      return;
    }
    this.dispatchEvent(new CustomEvent('change', {
      detail: { value: newValue },
      bubbles: true
    }));
    this.activeIndex = index;
    this.activeId = 'option-' + index;
  }
}
