        this.items = this.tasks.map((t) => ({ id: t.id, label: t.label, done: t.done }));
    }

    propertyChangedCallback(name, oldValue, newValue) {
        super.propertyChangedCallback(name, oldValue, newValue);
        if (name === 'tasks') {
            this.items = newValue ? newValue.map((t) => ({ id: t.id, label: t.label, done: t.done })) : [];
        }
        if (name === 'heading') {
            this.heading = newValue ? newValue.toUpperCase() : '';
        }
    }

    get remaining() {
        return this.items.filter((task) => !task.done).length;
    }

    handleLabelChange(event) {
        this.newLabel = event.detail.value;
    }

    handleAdd() {
        const trimmed = this.newLabel.trim();
        if (!trimmed) {
            return;
        }
        this.items.push({ id: `new-${this.nextId++}`, label: trimmed, done: false });
        this.dispatchEvent(new CustomEvent('taskadded', { detail: { label: trimmed } }));
        this.newLabel = '';
    }

    handleToggle(event) {
        const task = this.items.find((t) => t.id === event.target.dataset.id);
        if (task) {
            task.done = !task.done;
        }
    }
}
