public class EmployerService {

    public static void setCurrentEmployers(Map<Id, Id> employerByContactId) {
        if (employerByContactId == null || employerByContactId.isEmpty()) {
            return;
        }

        Set<Id> contactIds = employerByContactId.keySet();

        // Query 1: Retrieve current primary affiliations for the contacts in the map
        Map<Id, npe5__Affiliation__c> contactToCurrentAff = new Map<Id, npe5__Affiliation__c>();
        for (npe5__Affiliation__c aff : [
            SELECT Id, npe5__Contact__c, npe5__Organization__c, npe5__Status__c, npe5__EndDate__c
            FROM npe5__Affiliation__c
            WHERE npe5__Contact__c IN :contactIds
            AND npe5__Status__c = 'Current'
        ]) {
            contactToCurrentAff.put(aff.npe5__Contact__c, aff);
        }

        // Query 2: Retrieve each contact's primary affiliation lookup field
        Map<Id, Contact> contactToLookup = new Map<Id, Contact>();
        for (Contact con : [
            SELECT Id, npsp__Primary_Affiliation__c
            FROM Contact
            WHERE Id IN :contactIds
        ]) {
            contactToLookup.put(con.Id, con);
        }

        List<SObject> dmlRecords = new List<SObject>();

        for (Id contactId : contactIds) {
            Id orgId = employerByContactId.get(contactId);
            npe5__Affiliation__c currentAff = contactToCurrentAff.get(contactId);

            // If the organization is already the contact's primary affiliation, nothing changes
            if (currentAff != null && currentAff.npe5__Organization__c == orgId) {
                continue;
            }

            // If a current primary affiliation exists, end it (Status=Former, EndDate=today).
            // NPSP maintains the Primary flag automatically via its standard mechanism.
            if (currentAff != null) {
                currentAff.npe5__Status__c = 'Former';
                currentAff.npe5__EndDate__c = Date.today();
                dmlRecords.add(currentAff);
            }

            // Create a new primary affiliation for the new employer organization.
            // NPSP will mark this as the current primary affiliation via its standard mechanism.
            npe5__Affiliation__c newAff = new npe5__Affiliation__c();
            newAff.npe5__Contact__c = contactId;
            newAff.npe5__Organization__c = orgId;
            newAff.npe5__Status__c = 'Current';
            newAff.npe5__StartDate__c = Date.today();
            dmlRecords.add(newAff);

            // Update the contact's primary affiliation lookup to point to the new organization.
            Contact con = contactToLookup.get(contactId);
            if (con != null) {
                con.npsp__Primary_Affiliation__c = orgId;
                dmlRecords.add(con);
            }
        }

        if (!dmlRecords.isEmpty()) {
            Database.update(dmlRecords);
        }
    }
}
