public class OPP_MajorGiftFollowUp_TDTM extends npsp.TDTM_Runnable {

    @override
    public npsp.TDTM_Runnable.DmlWrapper run(List<SObject> newList, List<SObject> oldList, npsp.TDTM_Runnable.Action triggerAction, Schema.DescribeSObjectResult objResult) {
        // Identify opportunities that are newly Closed Won with Amount >= 5000
        List<Opportunity> newQualified = new List<Opportunity>();
        for (SObject obj : newList) {
            if (obj is Opportunity) {
                Opportunity opp = (Opportunity) obj;
                if (opp.IsClosed && opp.IsWon && opp.Amount >= 5000) {
                    newQualified.add(opp);
                }
            }
        }

        if (newQualified.isEmpty()) {
            return new npsp.TDTM_Runnable.DmlWrapper();
        }

        // Query existing tasks for these opportunities to avoid duplicates
        Set<Id> oppIds = new Set<Id>();
        for (Opportunity o : newQualified) {
            oppIds.add(o.Id);
        }
        List<Task> existingTasks = [
            SELECT Id, WhatId FROM Task
            WHERE WhatId IN :oppIds
            AND Subject = 'Major gift thank-you call'
            AND Status = 'Not Started'
        ];
        Set<Id> idsWithExistingTask = new Set<Id>();
        for (Task t : existingTasks) {
            idsWithExistingTask.add(t.WhatId);
        }

        // Remove opportunities that already have such a task
        List<Opportunity> toProcess = new List<Opportunity>();
        for (Opportunity o : newQualified) {
            if (!idsWithExistingTask.contains(o.Id)) {
                toProcess.add(o);
            }
        }

        if (toProcess.isEmpty()) {
            return new npsp.TDTM_Runnable.DmlWrapper();
        }

        // Build tasks
        List<Task> tasks = new List<Task>();
        for (Opportunity o : toProcess) {
            Task t = new Task();
            t.Subject = 'Major gift thank-you call';
            t.Priority = 'High';
            t.Status = 'Not Started';
            t.WhatId = o.Id;
            t.WhoId = o.npsp__Primary_Contact__c; // may be null
            t.OwnerId = o.OwnerId;
            if (o.CloseDate != null) {
                t.ActivityDate = o.CloseDate.addDays(3);
            }
            tasks.add(t);
        }

        // Return wrapper to let TDTM insert tasks
        npsp.TDTM_Runnable.DmlWrapper wrapper = new npsp.TDTM_Runnable.DmlWrapper();
        wrapper.newList = tasks;
        return wrapper;
    }
}
