public with sharing class TA_Contact_PreventDuplicateEmail 
    implements TriggerAction.BeforeInsert, TriggerAction.BeforeUpdate {

    public void beforeInsert(List<SObject> triggerNew) {
        List<Contact> newContacts = (List<Contact>) triggerNew;
        Set<String> seenKeys = new Set<String>();
        for (Contact c : newContacts) {
            // Contacts without an Account or without an Email are not checked
            if (c.AccountId == null || c.Email == null) continue;
            String key = c.AccountId + '|' + c.Email.toLowerCase();
            if (seenKeys.contains(key)) {
                c.addError('Another contact on this account already uses this email address.');
            } else {
                seenKeys.add(key);
            }
        }
    }

    public void beforeUpdate(List<SObject> triggerNew, List<SObject> triggerOld) {
        List<Contact> newContacts = (List<Contact>) triggerNew;
        List<Contact> oldContacts = (List<Contact>) triggerOld;
        Map<Id, Contact> oldMap = new Map<Id, Contact>(oldContacts);
        Set<String> seenKeys = new Set<String>();
        for (Contact c : newContacts) {
            Contact o = oldMap.get(c.Id);
            // Only check contacts whose Email or AccountId changed
            Boolean emailChanged = (c.Email != o.Email);
            Boolean accountChanged = (c.AccountId != o.AccountId);
            if (!emailChanged && !accountChanged) continue;
            // Contacts without an Account or without an Email are not checked
            if (c.AccountId == null || c.Email == null) continue;
            String key = c.AccountId + '|' + c.Email.toLowerCase();
            if (seenKeys.contains(key)) {
                c.addError('Another contact on this account already uses this email address.');
            } else {
                seenKeys.add(key);
            }
        }
    }
}
