public with sharing class TA_Case_RollupOpenCount 
    implements TriggerAction.AfterInsert, 
               TriggerAction.AfterUpdate, 
               TriggerAction.AfterDelete, 
               TriggerAction.AfterUndelete {

    public void afterInsert(List<SObject> triggerNew) {
        handleRollup((List<Case>) triggerNew, null);
    }

    public void afterUpdate(List<SObject> triggerNew, List<SObject> triggerOld) {
        handleRollup((List<Case>) triggerNew, (List<Case>) triggerOld);
    }

    public void afterDelete(List<SObject> triggerOld) {
        handleRollup(null, (List<Case>) triggerOld);
    }

    public void afterUndelete(List<SObject> triggerNew) {
        handleRollup((List<Case>) triggerNew, null);
    }

    private void handleRollup(List<Case> newCases, List<Case> oldCases) {
        Set<Id> accountIds = new Set<Id>();

        // Collect Account IDs from new cases
        if (newCases != null) {
            for (Case c : newCases) {
                if (c.AccountId != null) {
                    accountIds.add(c.AccountId);
                }
            }
        }

        // Collect Account IDs from old cases (delete/undelete/update contexts)
        if (oldCases != null) {
            for (Case c : oldCases) {
                if (c.AccountId != null) {
                    accountIds.add(c.AccountId);
                }
            }
        }

        // For after-update: handle IsClosed changes and AccountId changes
        if (oldCases != null && newCases != null && newCases.size() == oldCases.size()) {
            for (Integer i = 0; i < newCases.size(); i++) {
                Case newCase = newCases[i];
                Case oldCase = oldCases[i];

                // Case was closed (IsClosed: false → true)
                if (oldCase.IsClosed == false && newCase.IsClosed == true) {
                    if (oldCase.AccountId != null) {
                        accountIds.add(oldCase.AccountId);
                    }
                }
                // Case was reopened (IsClosed: true → false)
                else if (oldCase.IsClosed == true && newCase.IsClosed == false) {
                    if (newCase.AccountId != null) {
                        accountIds.add(newCase.AccountId);
                    }
                }

                // AccountId was changed
                if (newCase.AccountId != oldCase.AccountId) {
                    if (oldCase.AccountId != null) {
                        accountIds.add(oldCase.AccountId);
                    }
                    if (newCase.AccountId != null) {
                        accountIds.add(newCase.AccountId);
                    }
                }
            }
        }

        if (accountIds.isEmpty()) return;

        // Single SOQL: count open cases per account
        Map<Id, Integer> openCaseCounts = new Map<Id, Integer>();
        for (AggregateResult ar : [
            SELECT AccountId, COUNT(Id) cnt 
            FROM Case 
            WHERE IsClosed = false AND AccountId IN :accountIds 
            GROUP BY AccountId
        ]) {
            openCaseCounts.put((Id)ar.get('AccountId'), (Integer)ar.get('cnt'));
        }

        // Prepare account updates — explicit 0 for accounts with no open cases
        List<Account> accountsToUpdate = new List<Account>();
        for (Id accId : accountIds) {
            Integer count = openCaseCounts.get(accId);
            if (count == null) {
                count = 0;
            }
            accountsToUpdate.add(new Account(Id = accId, FB_Open_Case_Count__c = count));
        }

        if (!accountsToUpdate.isEmpty()) {
            update accountsToUpdate;
        }
    }
}
